def kv_bytes(b, s, layers, heads, d_head, dtype_bytes=2):
    return 2 * b * s * layers * heads * d_head * dtype_bytes
print(kv_bytes(1, 32768, 32, 32, 128) / 2**30)  # 约 8.0 GiB fp16

def avg_seek(seq, head, order):
    pos, total = head, 0
    for i in order:
        total += abs(seq[i] - pos); pos = seq[i]
    return total / len(order)
seq = [98, 183, 37, 122, 14, 124, 65, 67]
print(avg_seek(seq, 53, list(range(len(seq)))))  # FCFS 顺序

cwnd, ssthresh = 1, 16
for step in range(20):
    if cwnd < ssthresh:
        cwnd *= 2          # 慢开始：指数增长
    else:
        cwnd += 1          # 拥塞避免：线性增长
    if cwnd > 40:          # 模拟一次丢包
        ssthresh = max(cwnd // 2, 2)
        cwnd = ssthresh
    print(step, cwnd, ssthresh)
